WITH RECURSIVE TagHierarchy AS (
    SELECT Id, TagName, ExcerptPostId, WikiPostId, 1 AS Level
    FROM Tags
    WHERE IsModeratorOnly = 0
    UNION ALL
    SELECT t.Id, t.TagName, t.ExcerptPostId, t.WikiPostId, th.Level + 1
    FROM Tags t
    JOIN TagHierarchy th ON t.Count < th.Count 
    WHERE th.Level < 3
),
RecentQuestionsWithBadges AS (
    SELECT q.Id AS QuestionId, q.Title, u.Id AS UserId, u.DisplayName,
           u.Reputation, q.CreationDate, q.Tags,
           JSON_ARRAYAGG(JSON_OBJECT(b.Name, b.Class) ORDER BY b.Date DESC) AS BadgesJson
    FROM Posts q
    LEFT JOIN Users u ON q.OwnerUserId = u.Id
    LEFT JOIN Badges b ON b.UserId = u.Id AND b.Date > q.CreationDate - INTERVAL '30 days'
    WHERE PostTypeId = 1
      AND q.CreationDate > NOW() - INTERVAL '60 days'
    GROUP BY q.Id, q.Title, u.Id, u.DisplayName, u.Reputation, q.CreationDate, q.Tags
),
